import{_ as n,C as o,o as c,c as p,ai as a,E as t}from"./chunks/framework.XEs52zTF.js";const _=JSON.parse('{"title":"交互实验室","description":"","frontmatter":{"title":"交互实验室"},"headers":[],"relativePath":"lab.md","filePath":"lab.md"}'),d={name:"lab.md"};function l(r,e,i,b,h,m){const s=o("ExpressionLab");return c(),p("div",null,[e[0]||(e[0]=a('<h1 id="交互实验室-看见表达式的编译过程" tabindex="-1">交互实验室：看见表达式的编译过程 <a class="header-anchor" href="#交互实验室-看见表达式的编译过程" aria-label="Permalink to &quot;交互实验室：看见表达式的编译过程&quot;">​</a></h1><p>输入一段整数算术表达式，观察字符如何变成 Token、AST 和栈式字节码，再逐条执行。这是专为演示设计的浏览器微型编译器，支持 <code>+ - * / %</code>、一元正负号、括号和 int32 检查。它不支持完整 Sprout 的变量、函数、布尔或控制流；完整实现请下载 C++ 源码。</p><p>实验额外接受一元正号 <code>+3</code>，便于观察前缀运算；完整 Sprout 不接受一元 <code>+</code>，迁移表达式时应去掉它。两者采用相同的 int32 算术边界：<code>-2147483648 / -1</code> 报溢出，<code>-2147483648 % -1</code> 得到 0；正字面量 <code>2147483648</code> 本身无效，因此 <code>-(2147483648)</code> 也会被拒绝。实验中的 <code>ADD</code>、<code>MUL</code> 等是便于阅读的教学指令名，真实编译器使用 <code>+</code>、<code>*</code> 等操作码。</p>',3)),t(s),e[1]||(e[1]=a(`<h2 id="先预测-再点击" tabindex="-1">先预测，再点击 <a class="header-anchor" href="#先预测-再点击" aria-label="Permalink to &quot;先预测，再点击&quot;">​</a></h2><p>默认输入 <code>2 + 3 * (4 - 1)</code> 的结果为 11。AST 的根是加法，右子树是乘法，而减法位于乘法的右子树。编译器先为子表达式产生指令，再产生当前运算的指令，所以不需要 VM 再理解括号或运算符优先级。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PUSH 2      栈 [2]</span></span>
<span class="line"><span>PUSH 3      栈 [2, 3]</span></span>
<span class="line"><span>PUSH 4      栈 [2, 3, 4]</span></span>
<span class="line"><span>PUSH 1      栈 [2, 3, 4, 1]</span></span>
<span class="line"><span>SUB         栈 [2, 3, 3]</span></span>
<span class="line"><span>MUL         栈 [2, 9]</span></span>
<span class="line"><span>ADD         栈 [11]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>执行 <code>SUB</code> 时，先弹出右操作数 1，再弹出左操作数 4，计算的是 <code>4 - 1</code>。把顺序写反不会影响加法与乘法，却会破坏减法、除法和比较，因此测试不能只用交换律成立的运算。</p><h2 id="三个小实验" tabindex="-1">三个小实验 <a class="header-anchor" href="#三个小实验" aria-label="Permalink to &quot;三个小实验&quot;">​</a></h2><ol><li>输入 <code>20 - 5 - 3</code>。结果为什么是 12 而不是 18？对比 AST 的左右子树。</li><li>输入 <code>-7 / 2</code>。为什么结果是 -3？如果使用向下取整将得到什么？</li><li>输入 <code>1 / (3 - 3)</code>。Token 和 AST 都合法，为什么执行时仍失败？</li></ol><details><summary>展开解释</summary><p>减法在文法中为左结合，所以树表示 <code>(20 - 5) - 3</code>。整数除法向零截断，-3.5 截为 -3；向下取整则是 -4。除零需要知道运行时操作数，当前实验把它作为 VM 陷阱，而不是语法错误。更强的优化器可以提前发现常量除零，但必须保持语言所规定的失败行为。</p></details><h2 id="用本地编译器重做实验" tabindex="-1">用本地编译器重做实验 <a class="header-anchor" href="#用本地编译器重做实验" aria-label="Permalink to &quot;用本地编译器重做实验&quot;">​</a></h2><p>把表达式放入 <code>fn main() -&gt; int { print(表达式); return 0; }</code>，运行 <code>sprout --tokens</code>、<code>--ast</code>、<code>--bytecode</code> 和默认执行模式。浏览器微型实验的输出格式不承诺与 C++ 参考实现逐字相同；比较的重点是结构、求值顺序和计算结果。</p><p>下一步阅读<a href="./chapter07.html">第 7 章：递归下降</a>和<a href="./chapter11.html">第 11 章：字节码生成</a>，自己实现实验中观察到的过程。</p>`,10))])}const S=n(d,[["render",l]]);export{_ as __pageData,S as default};
